import{_ as a,c as r,o,a3 as e}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/usage.md","filePath":"zh-TW/guide/usage.md","lastUpdated":1786595765000}'),l={name:"zh-TW/guide/usage.md"};function n(i,t,s,d,g,h){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><h2 id="剪貼簿歷史" tabindex="-1">剪貼簿歷史 <a class="header-anchor" href="#剪貼簿歷史" aria-label="Permalink to &quot;剪貼簿歷史&quot;">​</a></h2><p>ClipboardxAI 從你的<strong>選單列</strong>運作。每當你複製某樣東西時，它就會被加入你的歷史紀錄中。</p><ul><li>點擊選單列圖示以開啟歷史面板。</li><li>將游標停留在某個項目上並按下動作快捷鍵，或點擊將它複製回剪貼板。</li><li>使用搜尋欄位，依文字尋找某個項目。</li></ul><h2 id="ai-工具視窗" tabindex="-1">AI 工具視窗 <a class="header-anchor" href="#ai-工具視窗" aria-label="Permalink to &quot;AI 工具視窗&quot;">​</a></h2><p><strong>AI 工具</strong>視窗是動作執行的地方。它採用左右分割的版面：</p><ul><li><strong>左側</strong> — 工具清單，分為以下群組： <ul><li><strong>內建 AI</strong> — 摘要、翻譯與其他 AI 動作。</li><li><strong>內建本地</strong> — 離線工具（擷取連結、統計計數、摺疊空白行）。</li><li><strong>已安裝</strong> — 你從 Marketplace 加入的動作。你可以拖曳來<strong>重新排序</strong>它們。</li></ul></li><li><strong>右側</strong> — 兩個窗格：一側是<strong>原始</strong>剪貼內容，另一側是<strong>結果</strong>。</li></ul><p>AI 工具會顯示「雲端」標記；本地工具則顯示「裝置」標記，因此你隨時都能知道某個動作是否使用了網路。</p><h2 id="執行動作" tabindex="-1">執行動作 <a class="header-anchor" href="#執行動作" aria-label="Permalink to &quot;執行動作&quot;">​</a></h2><ol><li>從左側清單選取一個工具（或接受智慧建議）。</li><li>目前的剪貼內容會出現在<strong>原始</strong>窗格中。</li><li>結果會在<strong>結果</strong>窗格中產生。</li></ol><h3 id="自動執行" tabindex="-1">自動執行 <a class="header-anchor" href="#自動執行" aria-label="Permalink to &quot;自動執行&quot;">​</a></h3><p>在視窗底部開啟 <strong>Auto-run on output（輸出時自動執行）</strong>。啟用後，當你複製內容的瞬間，所選工具就會自動執行——不需要手動點擊。本地工具永遠不會覆寫你的剪貼板，因此自動執行是安全的。</p><h2 id="內建本地工具" tabindex="-1">內建本地工具 <a class="header-anchor" href="#內建本地工具" aria-label="Permalink to &quot;內建本地工具&quot;">​</a></h2><p>這些工具完全在你的 Mac 上離線執行：</p><ul><li><strong>擷取連結（Extract Links）</strong> — 回傳文字中找到的所有 URL。</li><li><strong>統計計數（Count Stats）</strong> — 字數／字元數／行數／句數統計。</li><li><strong>摺疊空白行（Collapse Blank Lines）</strong> — 移除貼上文字中的空白行。</li></ul><h2 id="雲端-ai-設定" tabindex="-1">雲端 AI 設定 <a class="header-anchor" href="#雲端-ai-設定" aria-label="Permalink to &quot;雲端 AI 設定&quot;">​</a></h2><p>若要使用 AI 動作，請在 <strong>Settings → AI（設定 → AI）</strong> 中連接一個供應商：</p><ol><li>選擇一個供應商 — <strong>DeepSeek</strong>、<strong>MiniMax</strong>、<strong>Zhipu GLM</strong>、<strong>Kimi (Moonshot)</strong>、<strong>Mistral</strong>、<strong>Ollama</strong>（本地），或其他 OpenAI 相容的服務。</li><li>貼上你的 <strong>API key</strong>。它會儲存在 <strong>Keychain</strong> 中，絕不會以純文字寫入磁碟。</li><li>挑選一個模型。</li><li>雲端 AI 預設為關閉。啟用後，你的剪貼內容只會傳送給你所設定的供應商。</li></ol><p>若未設定 key，設定橫幅會在 AI 工具視窗內提醒你。</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><ol><li>從 AI 工具視窗開啟 <strong>Marketplace</strong>（或網站的 <a href="/zh-TW/marketplace/">Marketplace</a> 頁面）。</li><li>點擊某個動作上的 <strong>Install（安裝）</strong>。這會透過深層連結 <code>clipboardxai://install?action=&lt;id&gt;</code> 開啟應用程式，並將該動作加入你的<strong>已安裝</strong>清單。</li></ol><h2 id="鍵盤快捷鍵" tabindex="-1">鍵盤快捷鍵 <a class="header-anchor" href="#鍵盤快捷鍵" aria-label="Permalink to &quot;鍵盤快捷鍵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷鍵</th><th>動作</th></tr></thead><tbody><tr><td><code>Cmd+Shift+V</code></td><td>開啟剪貼簿歷史</td></tr><tr><td><code>Cmd+,</code></td><td>開啟設定</td></tr><tr><td><code>Cmd+W</code></td><td>關閉視窗</td></tr><tr><td><code>Cmd+Q</code></td><td>退出應用程式</td></tr></tbody></table><blockquote><p>確切的快捷鍵可能因建置版本而異；請在應用程式的 <strong>Settings → Shortcuts（設定 → 快捷鍵）</strong> 中查看。</p></blockquote><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p>開啟 <strong>ClipboardxAI → Settings（設定）</strong>（或 <code>Cmd+,</code>）：</p><ul><li><strong>General（一般）</strong>：語言、登入時啟動、外觀主題。</li><li><strong>AI</strong>：雲端供應商、模型與 API key（Keychain）。</li><li><strong>Actions（動作）</strong>：自動執行開關、排除的應用程式，以及工具順序。</li><li><strong>Privacy（隱私）</strong>：雲端 AI 加入選項、排除的應用程式，以及歷史紀錄控制。</li><li><strong>Marketplace</strong>：瀏覽並管理已安裝的動作。</li></ul>',27)])])}const p=a(l,[["render",n]]);export{u as __pageData,p as default};
